    def extract_json(self, text: str) -> Optional[Dict[str, Any]]:
        """从文本中提取JSON"""
        import re

        try:
            # 尝试查找JSON代码块
            json_pattern = r'```json\s*(.*?)\s*```'
            matches = re.findall(json_pattern, text, re.DOTALL | re.IGNORECASE)

            if matches:
